create table RB_PASSWORD (PWD_KEY VARCHAR(50) not null  ,PWD_TYPE VARCHAR(2) not null  ,CLIENT_NO VARCHAR(22) not null  ,PASSWORD VARCHAR(200) null  ,PASSWORD_EFFECT_DATE TIMESTAMP(3) null  ,PASSWORD_STATUS VARCHAR(1) null  ,CHANGE_IND VARCHAR(1) null  ,FAILURE_TIMES INT null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  ,PREV_FAILURE_TIMES INT null  ,DAY_FAILURE_TIMES INT null  ,DAC_VALUE VARCHAR(200) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(PWD_KEY,PWD_TYPE,CLIENT_NO));